/**
 * Description of a legacy (imperative DOM) portal, generated by
 * `tools/extract-legacy.mjs` from the original Matanho static prototype.
 *
 * Order matters: stylesheets and scripts are emitted in the exact order in
 * which the browser used to encounter them in the original HTML document.
 */
export interface LegacyManifest {
  /** Value of the original `<html lang>` attribute. */
  lang: string;
  /** Extra attributes that lived on the original `<html>` element. */
  htmlAttributes: Record<string, string>;
  /** Original `<title>`. */
  title: string;
  /** Original `<meta name="description">`. */
  description?: string;
  /** Public URLs of stylesheets, in cascade order. */
  styles: string[];
  /** Public URLs of scripts, in execution order. */
  scripts: string[];
}
